function parseCorrections(markdown) {
  // Correction notices are structured source data; drafts/decoys exist elsewhere.
  // Use anchored whole-heading regex and slice only this H2 section.
  const headingRe = /^## Correction Notices\s*$/m;
  const m = headingRe.exec(markdown);
  if (!m) return [];

  const sectionStart = m.index + m[0].length;
  const after = markdown.slice(sectionStart);
  const nextH2Idx = after.search(/^##\s+/m);
  const section = nextH2Idx === -1 ? after : after.slice(0, nextH2Idx);

  const notices = [];
  const blocks = section.split(/^###\s+/m).slice(1);
  for (const block of blocks) {
    const lines = block.split("\n");
    const noticeId = (lines[0] || "").trim();
    if (!noticeId.startsWith("CORR-")) continue;

    const entry = { notice_id: noticeId };
    for (const line of lines) {
      const trimmed = line.trim();
      const idx = trimmed.indexOf(":");
      if (idx === -1) continue;
      const key = trimmed.slice(0, idx).trim().toLowerCase();
      const value = trimmed.slice(idx + 1).trim();

      if (key === "targets") {
        entry.transaction_id = value;
      } else if (key === "field") {
        entry.field = value;
      } else if (key === "value") {
        entry.value = value;
      } else if (key === "effective") {
        entry.effective = value;
      }
    }

    // Only accept notices that have the minimum fields needed to apply.
    if (!entry.transaction_id || !entry.field) continue;
    notices.push(entry);
  }

  // Deterministic order: effective date, then notice id.
  notices.sort((a, b) => {
    const ea = a.effective || "";
    const eb = b.effective || "";
    if (ea < eb) return -1;
    if (ea > eb) return 1;
    return String(a.notice_id).localeCompare(String(b.notice_id));
  });

  return notices;
}

module.exports = { parseCorrections };
