function parseEmails(markdown) {
  // Email excerpts are structured under the `## Email Excerpts` section.
  // Binding policy about which emails apply is in the archive; here we parse
  // candidate compliance-related messages deterministically.
  const headingRe = /^## Email Excerpts\s*$/m;
  const m = headingRe.exec(markdown);
  if (!m) return [];

  const sectionStart = m.index + m[0].length;
  const after = markdown.slice(sectionStart);
  const nextH2Idx = after.search(/^##\s+/m);
  const section = nextH2Idx === -1 ? after : after.slice(0, nextH2Idx);

  // Split on "From:" lines (each message starts with From:)
  const parts = section.split(/^From:\s+/m).slice(1);
  const emails = [];

  for (let i = 0; i < parts.length; i += 1) {
    const block = "From: " + parts[i];

    const fromMatch = block.match(/^From:\s*(.+)$/im);
    const toMatch = block.match(/^To:\s*(.+)$/im);
    const subjectMatch = block.match(/^Subject:\s*(.+)$/im);
    const sentMatch = block.match(/^sent:\s*(\d{4}-\d{2}-\d{2})\s*$/im);

    const subject = subjectMatch ? subjectMatch[1].trim() : "";
    const txnMatch = subject.match(/\b(TXN-[0-9a-f-]+)\b/i);

    // Status changes are expressed as `status: <value>` in structured excerpts.
    const statusMatch = block.match(/^status:\s*(\w+)\s*$/im);
    const ownerMatch = block.match(/^owner:\s*(\S+)\s*$/im);

    const transaction_id = txnMatch ? txnMatch[1] : null;
    const status = statusMatch ? statusMatch[1].trim().toLowerCase() : null;
    const owner = ownerMatch ? ownerMatch[1].trim() : null;

    // Commentary says only compliance-addressed threads with transaction subjects apply.
    const to = toMatch ? toMatch[1].trim().toLowerCase() : "";
    const isCompliance = /compliance/.test(to);

    if (!fromMatch || !transaction_id) continue;
