  const section = nextH2Idx === -1 ? after : after.slice(0, nextH2Idx);

  const exceptions = [];
  const blocks = section.split(/^###\s+/m).slice(1);
  for (const block of blocks) {
    const title = (block.split("\n")[0] || "").trim();
    if (!/^Policy Exception\s*$/i.test(title)) continue;

    const txnMatch = block.match(/^transaction:\s*(TXN-[0-9a-f-]+)\s*$/im);
    const reasonMatch = block.match(/^reason:\s*(.+)\s*$/im);
    if (!txnMatch || !reasonMatch) continue;

    exceptions.push({
      transaction_id: txnMatch[1].trim(),
      reason: reasonMatch[1].trim(),
    });
  }

  return exceptions;
}

